    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["impeachment", "processo político para afastar o presidente da República quando ele comete crime de responsabilidade"],
        ["CPI", "Comissão Parlamentar de Inquérito: grupo de deputados e senadores que investiga uma denúncia"],
        ["confisco", "apreensão de bens pelo Estado, sem o consentimento do dono"],
        ["remessa de lucros", "envio, por empresas estrangeiras, de parte do lucro obtido no Brasil para o país de origem"],
        ["Plano Collor", "plano econômico de 1990 que bloqueou por 18 meses grande parte do dinheiro depositado em bancos e na poupança"],
        ["PC Farias", "empresário amigo e tesoureiro da campanha de Collor, acusado de comandar o esquema de corrupção"]
